// app/actions.js
'use server';
import { z } from 'zod';

const schema = z.object({
  email: z.string().email(),
});

export async function subscribe(formData) {
  const email = formData.get('email');
  const result = schema.safeParse({ email });
  if (!result.success) {
    return { error: 'Invalid email' };
  }
  // store in database
  return { success: true };
}
